import{_ as e,c as s,o as t,a0 as i}from"./chunks/framework.B4nOPtDa.js";const n="/Blog/assets/img/github-problems/git-push-error.png",g=JSON.parse('{"title":"為什麼 git push 發生錯誤？","description":"","frontmatter":{},"headers":[],"relativePath":"github-problems.md","filePath":"github-problems.md"}'),o={name:"github-problems.md"};function r(l,a,h,p,c,d){return t(),s("div",null,a[0]||(a[0]=[i('<h1 id="為什麼-git-push-發生錯誤" tabindex="-1">為什麼 git push 發生錯誤？ <a class="header-anchor" href="#為什麼-git-push-發生錯誤" aria-label="Permalink to &quot;為什麼 git push 發生錯誤？&quot;">​</a></h1><p>錯誤訊息如下：</p><p><img src="'+n+`" alt="這是圖片"></p><p>這個錯誤訊息表示你正在使用 HTTPS 方式連接 GitHub，<br> 但 GitHub 在 2021 年 8 月 13 日起 <strong>不再支援使用帳號密碼進行認證</strong>。</p><h3 id="快速檢查目前遠端網址是-https-還是-ssh" tabindex="-1">快速檢查目前遠端網址是 HTTPS 還是 SSH <a class="header-anchor" href="#快速檢查目前遠端網址是-https-還是-ssh" aria-label="Permalink to &quot;快速檢查目前遠端網址是 HTTPS 還是 SSH&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>git remote -v</span></span></code></pre></div><h2 id="✅-解法一-使用-personal-access-token-pat" tabindex="-1">✅ 解法一：使用 Personal Access Token (PAT) <a class="header-anchor" href="#✅-解法一-使用-personal-access-token-pat" aria-label="Permalink to &quot;✅ 解法一：使用 Personal Access Token (PAT)&quot;">​</a></h2><h4 id="步驟一-產生-token" tabindex="-1">步驟一：產生 Token <a class="header-anchor" href="#步驟一-產生-token" aria-label="Permalink to &quot;步驟一：產生 Token&quot;">​</a></h4><p>前往 GitHub 的 <a href="https://github.com/settings/tokens" target="_blank" rel="noreferrer">Token 產生頁面</a></p><ul><li>選擇「Fine-grained tokens」或「Classic tokens」都可以（如果不知道差別，選 classic 最簡單）</li><li>給 token 命名，並勾選 repo 權限</li><li>點選「Generate token」</li><li>複製這個 token（只能看到一次）</li></ul><br><h4 id="步驟二-更新-git-認證" tabindex="-1">步驟二 : 更新 Git 認證 <a class="header-anchor" href="#步驟二-更新-git-認證" aria-label="Permalink to &quot;步驟二 : 更新 Git 認證&quot;">​</a></h4><p>下次 git push 時，GitHub 會要求輸入帳號密碼</p><p>帳號： 輸入 GitHub 使用者名稱 <br> 密碼： 輸入剛剛產生的 Personal Access Token</p><h2 id="✅-解法二-改用-ssh-認證-更安全" tabindex="-1">✅ 解法二：改用 SSH 認證（更安全）<br> <a class="header-anchor" href="#✅-解法二-改用-ssh-認證-更安全" aria-label="Permalink to &quot;✅ 解法二：改用 SSH 認證（更安全）&lt;br&gt;&quot;">​</a></h2><p>(尚未使用過)</p><h4 id="步驟一-產生-ssh-金鑰-如果你還沒有" tabindex="-1">步驟一 : 產生 SSH 金鑰（如果你還沒有） <a class="header-anchor" href="#步驟一-產生-ssh-金鑰-如果你還沒有" aria-label="Permalink to &quot;步驟一 : 產生 SSH 金鑰（如果你還沒有）&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>ssh-keygen -t ed25519 -C &quot;your_email@example.com&quot;</span></span></code></pre></div><p>一直按 Enter，完成後會產生公私鑰。</p><h4 id="步驟二-加入-ssh-agent" tabindex="-1">步驟二 : 加入 SSH Agent <a class="header-anchor" href="#步驟二-加入-ssh-agent" aria-label="Permalink to &quot;步驟二 : 加入 SSH Agent&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>eval &quot;$(ssh-agent -s)&quot;</span></span>
<span class="line"><span>ssh-add ~/.ssh/id_ed25519</span></span></code></pre></div><h4 id="步驟三-將你的公鑰-ssh-id-ed25519-pub-加到-github" tabindex="-1">步驟三 : 將你的公鑰 (~/.ssh/id_ed25519.pub) 加到 GitHub <a class="header-anchor" href="#步驟三-將你的公鑰-ssh-id-ed25519-pub-加到-github" aria-label="Permalink to &quot;步驟三 : 將你的公鑰 (~/.ssh/id_ed25519.pub) 加到 GitHub&quot;">​</a></h4><p>到 <a href="https://github.com/settings/keys" target="_blank" rel="noreferrer">GitHub SSH 設定頁</a> 新增一組 SSH Key，把公鑰貼上去</p><h4 id="步驟四-修改-git-遠端網址為-ssh-版本" tabindex="-1">步驟四 : 修改 Git 遠端網址為 SSH 版本 <a class="header-anchor" href="#步驟四-修改-git-遠端網址為-ssh-版本" aria-label="Permalink to &quot;步驟四 : 修改 Git 遠端網址為 SSH 版本&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>git remote set-url origin git@github.com:YaLing0616/Blog.git</span></span></code></pre></div><p>可以正常 git push 囉!</p>`,26)]))}const b=e(o,[["render",r]]);export{g as __pageData,b as default};
